window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a497195ae0833518"]={"versions": [{"id": "FIG-a497195ae0833518", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturdiagramm / Speicherlayout-Diagramm zur statischen DID-Verwaltung innerhalb des AUTOSAR-Basissoftwaremoduls Debugging (DBG). Es visualisiert die Speicherorganisation und Tabellenbeziehungen für statisch konfigurierte Data Identifier (DIDs) im Speicherabbild des Steuergeräts.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei tabellarische Datenstrukturen sowie logische Zuordnungen:</p>\n<ul class=\"fig-list\">\n<li><strong>Statische DID-Referenztabelle (<code>Dbg_StatDIDRefTable</code>)</strong>: Indexierte Haupttabelle mit Einträgen für jeden konfigurierten DID (<code>DID AS index 0</code> bis <code>DID AS index n</code>) sowie einem abschließenden Grenzwächtereintrag (<code>DID AS last index (after last element)</code>).</li>\n<li><strong>Adresstabelle (Adressbereich)</strong>: Enthält Zeiger bzw. Startadressen (<code>Address0.1</code>, <code>Address0.2</code>, <code>Address1.1</code>, <code>Address2.1</code> bis <code>Address[n].1</code>), abgeschlossen mit <code>End of table</code>.</li>\n<li><strong>Größentabelle (Längenangaben)</strong>: Speichert die korrespondierenden Größen der Datenelemente in Bytes (<code>Size0.1</code>, <code>Size0.2</code>, <code>Size1.1</code>, <code>Size2.1</code> bis <code>Size[n].1</code>), abgeschlossen mit <code>End of table</code>.</li>\n<li><strong>Beziehungen</strong>: Durchgezogene Pfeile verweisen von den Indizes der Referenztabelle auf die Startadressen in der Adresstabelle; gepunktete Pfeile verbinden die Referenztabelle sowie korrespondierende Adress- und Größenfelder miteinander. Ein DID kann aus mehreren Teilelementen bestehen (z. B. <code>Element for DID0</code> mit zwei Einträgen für Adresse und Größe). Für den End-of-Table-Eintrag existiert kein Datenelement (<code>Not existing entry</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Auslesen oder Verarbeiten eines statischen DIDs erfolgt über einen zweistufigen Lookup:</p>\n<ol class=\"fig-list\">\n<li>Über die DID-Identifikation wird der passende Index in der Referenztabelle <code>Dbg_StatDIDRefTable</code> ermittelt.</li>\n<li>Der Tabelleneintrag adressiert das erste Element des DIDs in der Adress- und Größentabelle.</li>\n<li>Die Anzahl der zugehörigen Segmente bzw. Elemente ergibt sich aus der Differenz zum Folgeindex (oder dem Index des nächsten Elements), wodurch auch zusammengesetzte Datenelemente (z. B. <code>Address0.1</code>/<code>Size0.1</code> und <code>Address0.2</code>/<code>Size0.2</code> für <code>DID0</code>) sequenziell durchlaufen werden können.</li>\n<li>Der Eintrag <code>DID AS last index</code> markiert die Grenze des letzten gültigen DIDs (<code>DID[n]</code>) und zeigt auf die <code>End of table</code>-Markierungen, wodurch Bereichsüberläufe bei der Iteration verhindert werden.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Struktur erzwingt eine kompakte, ROM- bzw. Flash-effiziente Speicherung statischer Diagnosedaten (DID-Lookup) ohne dynamische Allokation. Das Vorhandensein eines Sentinel-Eintrags (<code>DID AS last index</code>) nach dem letzten regulären Element ist normativ erforderlich, um die Längen- und Elementanzahlberechnung über Pointer- bzw. Index-Arithmetik deterministisch und ohne separate Zählervariablen je DID-Eintrag im Debugging-Modul zu gewährleisten.</p>"}, {"id": "FIG-19d9445f580e9dad", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturdiagramm / Speicherlayout-Diagramm zur statischen DID-Verwaltung innerhalb des AUTOSAR-Basissoftwaremoduls Debugging (DBG). Es visualisiert die Speicherorganisation und Tabellenbeziehungen für statisch konfigurierte Data Identifier (DIDs) im Speicherabbild des Steuergeräts.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei tabellarische Datenstrukturen sowie logische Zuordnungen:</p>\n<ul class=\"fig-list\">\n<li><strong>Statische DID-Referenztabelle (<code>Dbg_StatDIDRefTable</code>)</strong>: Indexierte Haupttabelle mit Einträgen für jeden konfigurierten DID (<code>DID AS index 0</code> bis <code>DID AS index n</code>) sowie einem abschließenden Grenzwächtereintrag (<code>DID AS last index (after last element)</code>).</li>\n<li><strong>Adresstabelle (Adressbereich)</strong>: Enthält Zeiger bzw. Startadressen (<code>Address0.1</code>, <code>Address0.2</code>, <code>Address1.1</code>, <code>Address2.1</code> bis <code>Address[n].1</code>), abgeschlossen mit <code>End of table</code>.</li>\n<li><strong>Größentabelle (Längenangaben)</strong>: Speichert die korrespondierenden Größen der Datenelemente in Bytes (<code>Size0.1</code>, <code>Size0.2</code>, <code>Size1.1</code>, <code>Size2.1</code> bis <code>Size[n].1</code>), abgeschlossen mit <code>End of table</code>.</li>\n<li><strong>Beziehungen</strong>: Durchgezogene Pfeile verweisen von den Indizes der Referenztabelle auf die Startadressen in der Adresstabelle; gepunktete Pfeile verbinden die Referenztabelle sowie korrespondierende Adress- und Größenfelder miteinander. Ein DID kann aus mehreren Teilelementen bestehen (z. B. <code>Element for DID0</code> mit zwei Einträgen für Adresse und Größe). Für den End-of-Table-Eintrag existiert kein Datenelement (<code>Not existing entry</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Auslesen oder Verarbeiten eines statischen DIDs erfolgt über einen zweistufigen Lookup:</p>\n<ol class=\"fig-list\">\n<li>Über die DID-Identifikation wird der passende Index in der Referenztabelle <code>Dbg_StatDIDRefTable</code> ermittelt.</li>\n<li>Der Tabelleneintrag adressiert das erste Element des DIDs in der Adress- und Größentabelle.</li>\n<li>Die Anzahl der zugehörigen Segmente bzw. Elemente ergibt sich aus der Differenz zum Folgeindex (oder dem Index des nächsten Elements), wodurch auch zusammengesetzte Datenelemente (z. B. <code>Address0.1</code>/<code>Size0.1</code> und <code>Address0.2</code>/<code>Size0.2</code> für <code>DID0</code>) sequenziell durchlaufen werden können.</li>\n<li>Der Eintrag <code>DID AS last index</code> markiert die Grenze des letzten gültigen DIDs (<code>DID[n]</code>) und zeigt auf die <code>End of table</code>-Markierungen, wodurch Bereichsüberläufe bei der Iteration verhindert werden.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Struktur erzwingt eine kompakte, ROM- bzw. Flash-effiziente Speicherung statischer Diagnosedaten (DID-Lookup) ohne dynamische Allokation. Das Vorhandensein eines Sentinel-Eintrags (<code>DID AS last index</code>) nach dem letzten regulären Element ist normativ erforderlich, um die Längen- und Elementanzahlberechnung über Pointer- bzw. Index-Arithmetik deterministisch und ohne separate Zählervariablen je DID-Eintrag im Debugging-Modul zu gewährleisten.</p>"}], "trans": [{"from": "FIG-a497195ae0833518", "to": "FIG-19d9445f580e9dad", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
